package ru.neverland.townydistricts.model;

import java.util.*;

/** Pure, bounded planning analysis. Never loads chunks, reads Bukkit blocks or changes production bonuses. */
public final class DistrictAssessment {
    private DistrictAssessment(){}
    public static final int MAX_CLAIMS=20_000;
    public record Need(String id,String title,Set<String> projects){public Need{if(id==null||!id.matches("[a-z0-9_]{1,32}")||title==null||title.isBlank()||title.length()>80||projects==null||projects.isEmpty()||projects.size()>8||projects.stream().anyMatch(p->!p.matches("[a-z0-9_]{1,64}")))throw new IllegalArgumentException("Неверная городская служба");projects=Set.copyOf(projects);}}
    public record Settings(int range,Map<DistrictType,List<Need>> needs){public Settings{if(range<0||range>64)throw new IllegalArgumentException("Радиус служб: 0–64 участка");var copy=new EnumMap<DistrictType,List<Need>>(DistrictType.class);needs.forEach((type,list)->{var ids=new HashSet<String>();if(list.size()>8)throw new IllegalArgumentException("Не более 8 служб на тип района");for(var n:list)if(!ids.add(n.id()))throw new IllegalArgumentException("Повтор городской службы");copy.put(type,List.copyOf(list));});needs=Map.copyOf(copy);}}
    public record Input(List<District> districts,List<DistrictRules.Building> buildings,Map<String,DistrictType> types,Set<Cell> claimed,Set<UUID> loadedWorlds,Cell home,int cellSize,boolean buildingsAvailable,Settings settings){
        public Input{districts=List.copyOf(districts);buildings=List.copyOf(buildings);types=Map.copyOf(types);claimed=Set.copyOf(claimed);loadedWorlds=Set.copyOf(loadedWorlds);Objects.requireNonNull(settings);if(cellSize<1||cellSize>1024||districts.size()>128||buildings.size()>1024||claimed.size()>MAX_CLAIMS)throw new IllegalArgumentException("Слишком большая оценка района");}
    }
    public record Coverage(String id,String title,int served,int total,Set<String> sources,boolean known){public Coverage{sources=Set.copyOf(sources);}}
    public record Row(String id,boolean worldAvailable,int total,int owned,int connected,int distance,int matching,int other,int unfinished,int crossing,int unknownBuildings,boolean buildingsAvailable,List<Coverage> services){public Row{services=List.copyOf(services);}}
    public record Result(Map<String,Row> rows,int claimed,int reached,boolean homeKnown,int range){public Result{rows=Map.copyOf(rows);}}
    private static List<Cell> neighbors(Cell c){var result=new ArrayList<Cell>(4);if(c.x()<Integer.MAX_VALUE)result.add(new Cell(c.world(),c.x()+1,c.z()));if(c.x()>Integer.MIN_VALUE)result.add(new Cell(c.world(),c.x()-1,c.z()));if(c.z()<Integer.MAX_VALUE)result.add(new Cell(c.world(),c.x(),c.z()+1));if(c.z()>Integer.MIN_VALUE)result.add(new Cell(c.world(),c.x(),c.z()-1));return result;}
    private static Map<Cell,Integer> walk(Set<Cell> claimed,Collection<Cell> origins,int maximum){var distances=new HashMap<Cell,Integer>();var queue=new ArrayDeque<Cell>();for(var c:origins)if(claimed.contains(c)&&distances.putIfAbsent(c,0)==null)queue.add(c);while(!queue.isEmpty()){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("Оценка остановлена");var current=queue.removeFirst();int distance=distances.get(current);if(distance>=maximum)continue;for(var next:neighbors(current))if(claimed.contains(next)&&distances.putIfAbsent(next,distance+1)==null)queue.addLast(next);}return distances;}
    private record Reach(Map<Cell,Integer> distances,Map<Cell,String> sources){}
    private static Reach serve(Set<Cell> claimed,Map<Cell,String> origins,int maximum){var distances=new HashMap<Cell,Integer>();var sources=new HashMap<Cell,String>();var queue=new ArrayDeque<Cell>();var ordered=new ArrayList<>(origins.keySet());ordered.sort(Comparator.comparing((Cell c)->c.world().toString()).thenComparingInt(Cell::x).thenComparingInt(Cell::z));for(var c:ordered)if(claimed.contains(c)){distances.put(c,0);sources.put(c,origins.get(c));queue.add(c);}while(!queue.isEmpty()){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException("Оценка остановлена");var current=queue.removeFirst();int distance=distances.get(current);if(distance>=maximum)continue;for(var next:neighbors(current))if(claimed.contains(next)&&distances.putIfAbsent(next,distance+1)==null){sources.put(next,sources.get(current));queue.addLast(next);}}return new Reach(distances,sources);}
    private static Set<Cell> footprint(DistrictRules.Building b,int cellSize){if(b.world()==null||b.minX()>b.maxX()||b.minZ()>b.maxZ())return Set.of();int x1=Math.floorDiv(b.minX(),cellSize),x2=Math.floorDiv(b.maxX(),cellSize),z1=Math.floorDiv(b.minZ(),cellSize),z2=Math.floorDiv(b.maxZ(),cellSize);long width=(long)x2-x1+1,depth=(long)z2-z1+1;if(width>4096||depth>4096||width*depth>4096)return Set.of();var cells=new HashSet<Cell>();for(long x=x1;x<=x2;x++)for(long z=z1;z<=z2;z++)cells.add(new Cell(b.world(),(int)x,(int)z));return Set.copyOf(cells);}
    private static boolean completed(DistrictRules.Building b){return b.requiredLevel()>0&&b.level()>0;}
    public static Result calculate(Input input){
        boolean homeKnown=input.home()!=null&&input.claimed().contains(input.home());var fromHome=homeKnown?walk(input.claimed(),List.of(input.home()),MAX_CLAIMS):Map.<Cell,Integer>of();
        var areas=new HashMap<String,Set<Cell>>();var seen=new HashSet<String>();int footprintCells=0;for(var b:input.buildings()){if(!seen.add(b.id()))throw new IllegalArgumentException("Повтор площадки здания");var area=footprint(b,input.cellSize());if(area.isEmpty())throw new IllegalArgumentException("Неверная или слишком большая площадка здания");footprintCells=Math.addExact(footprintCells,area.size());if(footprintCells>65536)throw new IllegalArgumentException("Слишком большая суммарная площадка зданий");areas.put(b.id(),area);}
        // Multi-source service walks are capped at a small radius and shared by all districts.
        var serviceWalks=new HashMap<Need,Reach>();
        var orderedBuildings=input.buildings().stream().sorted(Comparator.comparing(DistrictRules.Building::id)).toList();
        if(input.buildingsAvailable())for(var list:input.settings().needs().values())for(var need:list)if(!serviceWalks.containsKey(need)){var origins=new HashMap<Cell,String>();for(var b:orderedBuildings)if(need.projects().contains(b.id())&&completed(b)){var area=areas.get(b.id());if(!area.isEmpty()&&input.claimed().containsAll(area))for(var cell:area)origins.putIfAbsent(cell,b.id());}serviceWalks.put(need,serve(input.claimed(),origins,input.settings().range()));}
        var rows=new LinkedHashMap<String,Row>();for(var d:input.districts()){
            boolean world=input.loadedWorlds().contains(d.cells().iterator().next().world());int owned=0,connected=0,distance=Integer.MAX_VALUE;for(var cell:d.cells()){if(input.claimed().contains(cell))owned++;var steps=fromHome.get(cell);if(steps!=null){connected++;distance=Math.min(distance,steps);}}
            int matching=0,other=0,unfinished=0,crossing=0,unknown=0;
            if(input.buildingsAvailable())for(var b:input.buildings()){var area=areas.get(b.id());if(area.isEmpty()||Collections.disjoint(d.cells(),area))continue;if(!d.cells().containsAll(area)){crossing++;continue;}if(!input.claimed().containsAll(area)){unknown++;continue;}if(!completed(b)){unfinished++;continue;}var type=input.types().get(b.id());if(type==null)unknown++;else if(type==d.type())matching++;else other++;}
            var coverage=new ArrayList<Coverage>();for(var need:input.settings().needs().getOrDefault(d.type(),List.of())){boolean known=world&&input.buildingsAvailable();int served=0;var ids=new HashSet<String>();if(known){var reachable=serviceWalks.getOrDefault(need,new Reach(Map.of(),Map.of()));for(var c:d.cells())if(input.claimed().contains(c)&&reachable.distances().containsKey(c)){served++;ids.add(reachable.sources().get(c));}}coverage.add(new Coverage(need.id(),need.title(),served,d.cells().size(),ids,known));}
            if(rows.put(d.id(),new Row(d.id(),world,d.cells().size(),owned,connected,distance==Integer.MAX_VALUE?-1:distance,matching,other,unfinished,crossing,unknown,input.buildingsAvailable(),coverage))!=null)throw new IllegalArgumentException("Повтор района");
        }
        return new Result(rows,input.claimed().size(),fromHome.size(),homeKnown,input.settings().range());
    }
}
